/* V3 customer-facing composition. All effects are local; source migration is separately evidenced. */
const V3={menu:false,housing:{type:'all',street:'all',max:700,saved:[],selected:'',room:'0',month:'2027-01',external:false,proof:false,sent:false},chat:{},faq:'',compare:[],providerCategory:'blocked',providerSaved:[]};
const visitorRoute=r=>!/^\/(staff|admin|management|master|coverage|workflow|conflicts)(\/|$)/.test(r);
const v3OriginalBody=vRenderBody,v3OriginalAssistant=vAssistant,v3OriginalFooter=footer;
const v3Groups=()=>[
 [t('Studium','Study'),[['/studienkolleg','Studienkolleg'],['/admission',t('Voraussetzungen','Entry requirements')],['/studienkolleg/ablauf-termine',t('Ablauf & Semester','Journey & semesters')],['/hochschule/suche',t('Hochschulen & Studiengänge','Universities & programmes')],['/hochschule/vergleich',t('Studiengänge vergleichen','Compare programmes')]]],
 [t('Deutsch & Prüfungen','German & exams'),[['/sprachschule',t('Deutsch A1–C1','German A1–C1')],['/sprachschule/einstufung',t('Einstufung','Placement')],['/sprachschule/selbstlernen',t('Selbstlernen','Self-study')],['/pruefungszentrum',t('Prüfungszentrum','Examination centre')],['/studienkolleg/fsp','Feststellungsprüfung']]],
 [t('Wohnen','Housing'),[['/wohnen','Stay in Aachen'],['/wohnen/suche',t('Zimmer finden','Find a room')],['/wohnen/extern',t('Anfrage ohne Kursteilnahme','Enquire without a course')]]],
 [t('Ankommen','Settle in'),[['/services',t('Start in Deutschland','Start in Germany')],['/services/vergleich',t('Sperrkonto & Versicherung','Blocked account & insurance')],['/services/visa',t('Visum & Anreise','Visa & arrival')]]],
 [t('Über uns','About us'),[['/team',t('Unser Team','Our team')],['/campus',t('Campus & Aachen','Campus & Aachen')],['/wissen',t('Wissen & FAQ','Knowledge & FAQ')],['/kontakt',t('Kontakt','Contact')],['/partner',t('Für Partner','For partners')]]]
];
function v3Header(){const r=route();return `<div class="preview-note">${t('Interaktive Vorschau','Interactive preview')} <span>· ${t('Anfragen und Buchungen werden nicht versendet','Enquiries and bookings are not sent')}</span></div><header class="v3-header"><a href="#/" class="v3-brand" aria-label="${t('Studienkolleg Aachen Startseite','Studienkolleg Aachen home')}"><img src="assets/studienkolleg-logo.png" alt="Studienkolleg Aachen"></a><nav class="v3-nav" aria-label="${t('Hauptnavigation','Main navigation')}">${v3Groups().map(([label,items])=>`<details class="nav-group"><summary>${label}<span>⌄</span></summary><div>${items.map(([to,name])=>`<a href="#${to}" ${r===to?'aria-current="page"':''}>${name}${arrow}</a>`).join('')}</div></details>`).join('')}</nav><div class="v3-header-actions"><button class="lang" data-action="language" aria-label="${t('Sprache auf Englisch wechseln','Switch language to German')}">${state.lang.toUpperCase()}</button><a class="account-link" href="#/mein-bereich">${t('Mein Bereich','My area')}</a>${link(t('Bewerben','Apply'),'/apply','small')}<button class="v3-menu-button" data-v3="menu" aria-expanded="${V3.menu}">${t('Menü','Menu')}</button></div></header>${V3.menu?`<nav class="v3-mobile-nav">${v3Groups().map(([l,items])=>`<details><summary>${l}</summary>${items.map(([to,n])=>`<a href="#${to}">${n}</a>`).join('')}</details>`).join('')}</nav>`:''}`}
const v3Section=(eyebrow,title,body,cls='')=>`<section class="v3-section ${cls}"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${body}</section>`;
const v3Card=(title,text,to,label=t('Mehr erfahren','Learn more'),image='')=>`<article class="v3-card">${image?`<img src="${image}" alt="${esc(title)}" loading="lazy">`:''}<div><h3>${title}</h3><p>${text}</p><a class="text-link" href="#${to}">${label}${arrow}</a></div></article>`;
function v3Home(){return `<section class="v3-hero"><div class="v3-hero-copy"><span class="eyebrow">STUDIENKOLLEG AACHEN</span><h1>${t('Dein Weg nach<br><em>Deutschland.</em>','Your path to<br><em>Germany.</em>')}</h1><p>${t('Studienvorbereitung, Deutsch und ein neues Zuhause. Wir begleiten dich von deiner ersten Frage bis zum nächsten Schritt ins Studium.','University preparation, German and a new home. We guide you from your first question to your next step towards university.')}</p><div class="actions">${link(t('Passenden Kurs finden','Find your programme'),'/studienkolleg')}${link(t('Beratung vereinbaren','Arrange guidance'),'/beratung','secondary')}</div></div><img class="v3-hero-person" src="assets/hero-woman.webp" alt="${t('Persönliche Begleitung am Studienkolleg Aachen','Personal guidance at Studienkolleg Aachen')}"></section>${v3Section(t('DEIN ZIEL. DEIN WEG.','YOUR GOAL. YOUR PATH.'),t('Was möchtest du als Nächstes erreichen?','What would you like to do next?'),`<div class="v3-card-grid">${v3Card(t('Studium vorbereiten','Prepare for university'),t('T-, M-, W- oder kombinierter M/T-Kurs: Entdecke den Weg in deine Fachrichtung.','T, M, W or combined M/T course: explore the route to your subject.'),'/studienkolleg')}${v3Card(t('Deutsch lernen','Learn German'),t('Von A1 bis C1: Sprachkenntnisse aufbauen und den passenden Einstieg finden.','From A1 to C1: build language skills and find your starting point.'),'/sprachschule')}${v3Card(t('In Aachen wohnen','Live in Aachen'),t('Möblierte Einzel- und Doppelzimmer entdecken und deinen Einzug planen.','Explore furnished single and shared rooms and plan your move.'),'/wohnen')}</div>`)}${v3Section(t('PERSÖNLICH AN DEINER SEITE','PERSONALLY BY YOUR SIDE'),t('Ankommen beginnt mit einem Gespräch.','Settling in starts with a conversation.'),`<div class="v3-editorial"><img src="assets/laura-saboor.jpg" alt="Laura Saboor" loading="lazy"><div><h3>Laura Saboor</h3><span class="subtle">Managing Director · W2G Academy GmbH</span><p>${t('Ein neuer Studienweg bringt viele Fragen mit sich. Unser Team unterstützt dich bei der Orientierung, der Vorbereitung deiner Bewerbung und dem Ankommen in Aachen.','A new academic pathway brings many questions. Our team supports your orientation, application preparation and arrival in Aachen.')}</p>${link(t('Team kennenlernen','Meet the team'),'/team','secondary')}</div></div>`)}${v3Section(t('LERNEN. BEGEGNEN. WEITERKOMMEN.','LEARN. CONNECT. PROGRESS.'),t('Ein Einblick in deinen Alltag.','A glimpse of your daily life.'),`<div class="v3-card-grid two">${v3Card(t('Gemeinsam lernen','Learning together'),t('Unterricht, Austausch und Vorbereitung auf deinen nächsten Bildungsabschnitt.','Classes, exchange and preparation for your next stage of education.'),'/campus',t('Campus entdecken','Explore campus'),'assets/campus-classroom.jpg')}${v3Card(t('Deine Bewerbung vorbereiten','Prepare your application'),t('Sprachstand, Bildungsnachweise und Motivation: Schritt für Schritt zusammenstellen.','Language level, academic records and motivation: prepare step by step.'),'/admission',t('Voraussetzungen ansehen','View requirements'),'assets/campus-workshop.jpg')}</div>`)}${v3Section(t('DEIN START IN DEUTSCHLAND','YOUR START IN GERMANY'),t('Mehr als nur ein Kurs.','More than a course.'),`<div class="v3-service-links">${[['/hochschule/suche',t('Hochschulen & Studiengänge vergleichen','Compare universities & programmes')],['/services/vergleich',t('Sperrkonto & Versicherung auswählen','Explore blocked accounts & insurance')],['/wohnen/suche',t('Dein Zimmer in Aachen finden','Find your room in Aachen')],['/services/visa',t('Visum & Anreise vorbereiten','Prepare your visa & arrival')]].map(([to,l])=>`<a href="#${to}">${l}${arrow}</a>`).join('')}</div>`,'soft')}${v3Section(t('FRAGEN VOR DEM START','BEFORE YOU BEGIN'),t('Gut zu wissen.','Good to know.'),v3FaqItems().slice(0,4).map(x=>`<details class="v3-faq"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')+link(t('Alle Antworten ansehen','View all answers'),'/wissen','secondary'))}`}
function v3FaqItems(){return [[t('Welcher Kurs passt zu meinem Studienwunsch?','Which programme fits my study goal?'),t('Der T-Kurs richtet sich an technische und naturwissenschaftliche Studienrichtungen, der M-Kurs an Medizin und Biologie und der W-Kurs an Wirtschafts- und Sozialwissenschaften. Der kombinierte M/T-Weg verbindet zwei Fachrichtungen. Die individuelle Passung klärst du mit der Beratung.','T focuses on technical and scientific subjects, M on medicine and biology, and W on economics and social sciences. The combined M/T pathway covers two subject groups. Discuss your individual fit with the advisory team.')],[t('Welche Unterlagen brauche ich?','Which documents do I need?'),t('Halte deine Schulzeugnisse, vorhandene Sprachzertifikate und Informationen zu deinem bisherigen Bildungsweg bereit. Welche Übersetzungen und weiteren Nachweise in deinem Fall nötig sind, wird bei der Beratung geklärt.','Prepare your school records, existing language certificates and education history. The advisory team will clarify translations and additional evidence for your case.')],[t('Kann ich auch ohne Studienkolleg-Kurs ein Zimmer anfragen?','Can I enquire about a room without a Studienkolleg course?'),t('Ja, es gibt einen eigenen Anfrageweg für externe Interessenten. Dafür wird ein geeigneter Nachweis angefragt. Ein Zimmer ist erst nach Bestätigung und Vertrag verbindlich vereinbart.','Yes, there is a separate enquiry pathway for external applicants, with supporting evidence. A room is only agreed after confirmation and contract.')],[t('Wo finde ich aktuelle Preise und Termine?','Where can I find current prices and dates?'),t('Kurs, Starttermin und Leistungsumfang gehören zusammen. Lass dir das aktuelle Angebot für deinen gewünschten Einstieg bestätigen. Bei Zimmern findest du veröffentlichte Orientierungspreise; freie Plätze werden individuell bestätigt.','Your course, start date and service scope belong together. Request the current offer for your desired intake. Rooms show published indicative rates; availability is confirmed individually.')],[t('Wie beginne ich meine Bewerbung?','How do I start my application?'),t('Wähle deinen gewünschten Bildungsweg, bereite deine Nachweise vor und beginne mit der Bewerbung. Im persönlichen Bereich behältst du deine nächsten Schritte im Blick.','Choose your pathway, prepare evidence and begin your application. Your personal area helps you follow the next steps.')]]}
function v3Footer(){return `<footer class="v3-footer"><div><img src="assets/studienkolleg-logo.png" alt="Studienkolleg Aachen"><p>W2G Academy GmbH<br>Theaterstraße 30–32<br>52062 Aachen</p><a href="mailto:info@stk-aachen.de">info@stk-aachen.de</a><br><a href="tel:+4924199032292">+49 241 990 322 92</a></div><div><h3>${t('Dein Weg','Your pathway')}</h3>${[['/studienkolleg','Studienkolleg'],['/sprachschule',t('Deutsch lernen','Learn German')],['/pruefungszentrum',t('Prüfungen','Exams')],['/wohnen','Stay in Aachen']].map(([r,l])=>`<a href="#${r}">${l}</a>`).join('')}</div><div><h3>${t('Gut informiert','Stay informed')}</h3>${[['/wissen','FAQ & Wissen'],['/kontakt',t('Kontakt','Contact')],['/preise',t('Preise & Angebote','Prices & offers')],['/partner',t('Partner','Partners')]].map(([r,l])=>`<a href="#${r}">${l}</a>`).join('')}</div><div class="v3-footer-bottom"><span>© Studienkolleg Aachen</span>${[['/rechtliches',t('Impressum','Legal notice')],['/datenschutz',t('Datenschutz','Privacy')],['/agb','AGB'],['/widerruf',t('Widerruf','Cancellation')]].map(([r,l])=>`<a href="#${r}">${l}</a>`).join('')}<button data-action="privacy">${t('Vorschau-Datenschutz','Preview privacy')}</button></div></footer>`}
function v3Guidance(a){const r=route(),housing=r.startsWith('/wohnen'),uni=r.startsWith('/hochschule'),lang=r.startsWith('/sprachschule'),exam=r.startsWith('/pruefungszentrum');return housing?[t('Finde dein Zuhause.','Find your new home.'),t('Einzelzimmer oder gemeinsam wohnen? Ich helfe dir, die Auswahl einzugrenzen.','A single room or shared living? I can help narrow your options.'),[['Zimmer vergleichen','Compare rooms','/wohnen/suche'],['Ohne Kurs anfragen','Enquire without a course','/wohnen/extern']]]:uni?[t('Was möchtest du studieren?','What would you like to study?'),t('Vergleiche Studienrichtungen und halte fest, welche Voraussetzungen du noch klären möchtest.','Compare subjects and note the requirements you still need to clarify.'),[['Studiengänge suchen','Search programmes','/hochschule/suche'],['Meine Auswahl vergleichen','Compare my selection','/hochschule/vergleich']]]:lang?[t('Dein Deutsch. Dein nächster Schritt.','Your German. Your next step.'),t('Dein Lernziel und deine bisherigen Kenntnisse zeigen, welcher Einstieg passt.','Your learning goal and existing skills guide your starting point.'),[['Sprachstufen ansehen','Explore levels','/sprachschule'],['Einstufung vorbereiten','Prepare placement','/sprachschule/einstufung']]]:exam?[t('Gut vorbereitet zur Prüfung.','Prepare for your exam.'),t('Finde das richtige Prüfungsformat und kläre, wie du dich vorbereitest.','Find the right exam format and learn how to prepare.'),[['Prüfungen ansehen','Explore exams','/pruefungszentrum'],['Frage an die Beratung','Ask the team','/beratung']]]:[t('Wir finden deinen nächsten Schritt.','Let’s find your next step.'),t('Du musst noch nicht alles wissen. Was möchtest du in Deutschland erreichen?','You do not need every answer yet. What would you like to achieve in Germany?'),[['Passenden Kurs finden','Find my programme','/studienkolleg'],['Voraussetzungen klären','Explore requirements','/admission']]]}
function v3Assistant(a){if(!visitorRoute(route()))return v3OriginalAssistant(a);const context=(route().startsWith('/portal')&&!/^\/portal\/(applicant|student)(\/|$)/.test(route()))?'portal:'+route().split('/').slice(1,3).join('/'):'visitor:journey';V2.context=context;V2.notes[context]??={brief:'',messages:[]};const m=V2.notes[context],g=v3Guidance(a);return `<aside id="context-companion" class="v3-companion" aria-label="${t('Deine Beratungshilfe','Your guidance assistant')}"><div class="v3-companion-top"><span class="v3-orbit">${arrow}</span><div><b>${t('Dein Studienbegleiter','Your study companion')}</b><small>${t('Für deine Fragen & nächsten Schritte','For your questions & next steps')}</small></div></div><div class="v3-conversation"><span class="eyebrow">${t('GEMEINSAM WEITER','YOUR NEXT STEP')}</span><h2>${g[0]}</h2><p>${g[1]}</p><div class="v3-suggestions">${g[2].map(([de,en,to])=>`<a href="#${to}">${t(de,en)}${arrow}</a>`).join('')}</div><div class="v3-chat-log" aria-live="polite">${m.messages.map(x=>`<div class="chat-bubble ${x.role}">${esc(x.text)}</div>`).join('')}</div><details class="v3-note"><summary>${t('Mein Beratungsbrief','My guidance brief')}${m.brief?' •':''}</summary><p>${esc(m.brief)||t('Sammle deine Fragen für das persönliche Gespräch.','Collect questions for your conversation.')}</p><button data-v2="context-brief">${t('Bearbeiten','Edit')}${arrow}</button></details></div><form id="v3-chat-form" class="v3-compose"><label for="v3-question">${t('Was möchtest du wissen?','What would you like to know?')}</label><div><textarea id="v3-question" aria-label="${t('Was möchtest du wissen?','What would you like to know?')}" maxlength="500" placeholder="${t('Zum Beispiel: Welcher Kurs passt zu mir?','For example: Which course fits me?')}"></textarea><button aria-label="${t('Frage stellen','Ask question')}" type="submit">${arrow}</button></div><small>${t('Simulierte Beratung · keine Live-KI · bitte nur Beispieldaten','Simulated guidance · not live AI · sample data only')}</small></form></aside>`}
function v3Housing(){const r=route();if(r==='/wohnen/extern'||r==='/wohnen/anfrage')return v3HousingEnquiry(r);if(r.includes('/objekt/')){const id=r.split('/')[3],h=MIGRATED_HOUSING.find(x=>x.id===id);if(h)return v3HousingDetail(h);}const list=MIGRATED_HOUSING.filter(h=>(V3.housing.type==='all'||h.type===V3.housing.type)&&(V3.housing.street==='all'||h.name===V3.housing.street)&&h.publishedRent<=V3.housing.max);return `<section class="v3-page-intro housing-intro"><span class="eyebrow">STAY IN AACHEN</span><h1>${t('Dein Zuhause.<br>Dein neuer Anfang.','Your home.<br>Your new beginning.')}</h1><p>${t('Möblierte Zimmer in Aachen. Entdecke Kapellenstraße, Vaalser Straße und Römerstraße — und finde den Ort, an dem du ankommen möchtest.','Furnished rooms in Aachen. Explore Kapellenstraße, Vaalser Straße and Römerstraße — and find the place you would like to call home.')}</p></section><section class="v3-section housing-search"><form id="v3-housing-filter" class="v3-filter"><label>${t('Zimmerart','Room type')}<select id="housing-type"><option value="all">${t('Alle Zimmer','All rooms')}</option><option value="single" ${V3.housing.type==='single'?'selected':''}>${t('Einzelzimmer','Single room')}</option><option value="double" ${V3.housing.type==='double'?'selected':''}>${t('Doppelzimmer','Shared room')}</option></select></label><label>${t('Lage','Location')}<select id="housing-street"><option value="all">${t('Alle Lagen','All locations')}</option>${[...new Set(MIGRATED_HOUSING.map(x=>x.name))].map(n=>`<option ${n===V3.housing.street?'selected':''}>${n}</option>`).join('')}</select></label><label>${t('Bis €/Monat','Up to €/month')}<select id="housing-budget">${[450,550,600,700].map(n=>`<option value="${n}" ${n===V3.housing.max?'selected':''}>${n} €</option>`).join('')}</select></label><button class="btn" type="submit">${t('Zimmer finden','Find rooms')}${arrow}</button></form><div class="v3-results-head"><h2>${list.length} ${t(list.length===1?'Zimmerangebot':'Zimmerangebote',list.length===1?'room option':'room options')}</h2><span>${t('Verfügbarkeit auf Anfrage','Availability on request')}</span></div><div class="v3-card-grid two">${list.map(h=>`<article class="v3-property"><a href="#/wohnen/objekt/${h.id}"><img src="${h.images[0]}" alt="${t('Einblick in die Unterkunft','Inside the accommodation')} ${h.name}" loading="lazy"><span>${t(h.type==='single'?'Einzelzimmer':'Doppelzimmer',h.type==='single'?'Single room':'Shared room')}</span></a><div><small>AACHEN · ${t('MÖBLIERT','FURNISHED')}</small><h3><a href="#/wohnen/objekt/${h.id}">${h.name}</a></h3><p>${t('WLAN · Küche · Arbeitsplatz','Wi-Fi · kitchen · study desk')}</p><div class="v3-property-bottom"><div><b>${t('ab','from')} ${h.publishedRent} €</b><small>/${t(h.type==='double'?'Person · Monat':'Monat',h.type==='double'?'person · month':'month')}</small></div><a class="text-link" href="#/wohnen/objekt/${h.id}">${t('Ansehen','Explore')}${arrow}</a></div></div></article>`).join('')||`<div class="empty-state">${t('Keine Zimmer für diese Auswahl. Erhöhe dein Budget oder ändere die Lage.','No rooms match. Increase the budget or change the location.')}</div>`}</div><p class="v3-source-note">${t('Veröffentlichte Orientierungspreise von Stay in Aachen, abgerufen am 30.10.2026. Preis, Vertrag und freie Plätze werden für deinen Zeitraum bestätigt.','Published indicative rates from Stay in Aachen, retrieved 30 Oct 2026. Price, contract and availability are confirmed for your dates.')}</p></section>${v3Section(t('GUT ANKOMMEN','SETTLE IN'),t('Schon in Aachen? Noch auf dem Weg?','Already in Aachen? Still on your way?'),`<div class="v3-card-grid two">${v3Card(t('Ohne Kursteilnahme anfragen','Enquire without a course'),t('Du suchst unabhängig von einem Kurs ein Zimmer? Nutze die Anfrage für externe Interessenten.','Looking for a room independently of a course? Use the external enquiry pathway.'),'/wohnen/extern')}${v3Card(t('Dein Wohnalltag','Your housing journey'),t('Einzug, Mietunterlagen und Anliegen an einem Ort.','Move-in, rental documents and requests in one place.'),'/mein-bereich/wohnen')}</div>`)}`}
function v3HousingDetail(h){return `<div class="v3-breadcrumb"><a href="#/wohnen">Stay in Aachen</a> / ${h.name}</div><section class="v3-page-intro"><span class="eyebrow">${t(h.type==='single'?'EINZELZIMMER':'DOPPELZIMMER',h.type==='single'?'SINGLE ROOM':'SHARED ROOM')} · AACHEN</span><h1>${h.name}</h1><p>${t('Dein möblierter Rückzugsort zum Lernen, Wohnen und Ankommen.','Your furnished space to study, live and settle in.')}</p></section><section class="v3-section v3-gallery">${h.images.map((src,i)=>`<button data-v3="photo" data-value="${src}" aria-label="${t('Foto vergrößern','Enlarge photograph')} ${i+1}"><img src="${src}" alt="${h.name} · ${t('Unterkunft','Accommodation')} ${i+1}"></button>`).join('')}</section><section class="v3-section"><div class="v3-detail-grid"><div><h2>${t('Platz für deinen Alltag.','Room for your daily life.')}</h2><p>${t('Die Unterkunft bietet eine ausgestattete Küche, einen Arbeitsbereich, WLAN und ein Badezimmer. Die Zimmer sind möbliert; Bett und Schreibtisch gehören zur beschriebenen Ausstattung.','The accommodation offers an equipped kitchen, study space, Wi-Fi and a bathroom. Rooms are furnished, with a bed and desk among the published amenities.')}</p><div class="v3-amenities">${['WLAN','Küche','Arbeitsplatz','Möbliert'].map((s,i)=>`<span>${t(s,['Wi-Fi','Kitchen','Study desk','Furnished'][i])}</span>`).join('')}</div><h3>${t('So geht es weiter','What happens next')}</h3><ol class="v3-steps"><li>${t('Wunschzeitraum und Zimmer angeben','Choose dates and a room')}</li><li>${t('Rückmeldung zu Verfügbarkeit und Angebot erhalten','Receive availability and offer information')}</li><li>${t('Vertrag und Einzug persönlich abstimmen','Agree your contract and move-in')}</li></ol></div><div class="v3-booking-card"><span>${t('Veröffentlichter Orientierungspreis','Published indicative rate')}</span><h2>${t('ab','from')} ${h.publishedRent} € <small>/ ${t('Monat','month')}</small></h2>${h.type==='double'?`<p>${t('pro Person im Doppelzimmer','per person in a shared room')}</p>`:''}<p>${t('Kaution laut Website:','Deposit listed on website:')} ${h.deposit} €</p><label class="field">${t('Gewünschter Einzug','Preferred move-in')}<input type="month" id="v3-movein" value="${V3.housing.month}" min="2026-11"></label><button class="btn" data-v3="housing-enquire" data-value="${h.id}">${t('Unverbindlich anfragen','Make an enquiry')}${arrow}</button><small>${t('Keine Live-Verfügbarkeit. Die Vorschau versendet keine Anfrage.','No live availability. This preview does not send enquiries.')}</small></div></div><p class="v3-source-note"><a href="${h.source}" target="_blank" rel="noopener">${t('Angaben & Fotos: Stay in Aachen','Information & photography: Stay in Aachen')}</a> · 30.10.2026</p></section>`}
function v3HousingEnquiry(r){const h=MIGRATED_HOUSING.find(x=>x.id===V3.housing.selected),external=r.endsWith('extern')||V3.housing.external;return `<section class="v3-page-intro"><span class="eyebrow">STAY IN AACHEN</span><h1>${t('Dein Wohnwunsch.','Your housing enquiry.')}</h1><p>${h?`${h.name} · ${t('Zimmer','Room')} ${h.rooms[Number(V3.housing.room)]?.source_room_label||'1'} · ${V3.housing.month}`:t('Teile uns mit, wie du in Aachen wohnen möchtest.','Tell us how you would like to live in Aachen.')}</p></section><section class="v3-section">${V3.housing.sent?`<div class="v3-success"><h2>${t('Deine Musteranfrage ist vorbereitet.','Your sample enquiry is ready.')}</h2><p>${t('Im fertigen Ablauf erhältst du eine Rückmeldung zu passenden Zimmern, Verfügbarkeit und Unterlagen. Hier wurde nichts versendet und kein Zimmer reserviert.','In the completed service you receive information about rooms, availability and documents. Nothing was sent and no room was reserved here.')}</p>${link(t('Weitere Zimmer ansehen','Explore more rooms'),'/wohnen','secondary')}</div>`:`<form id="v3-enquiry" class="v3-enquiry"><span class="v3-local-label">${t('Formularvorschau · bitte nur Beispieldaten','Form preview · sample data only')}</span><div class="form-grid"><label class="field">${t('Vorname','First name')}<input required placeholder="Alex" name="first" autocomplete="off"></label><label class="field">${t('E-Mail','Email')}<input required type="email" placeholder="alex@example.com" name="email" autocomplete="off"></label><label class="field">${t('Einzug','Move-in')}<input type="month" required value="${V3.housing.month}"></label><label class="field">${t('Zimmerwunsch','Room preference')}<select><option>${h?.name||t('Noch offen','Not decided')}</option><option>${t('Einzelzimmer','Single room')}</option><option>${t('Doppelzimmer','Shared room')}</option></select></label></div><label class="check-option"><input id="v3-external" type="checkbox" ${external?'checked':''}>${t('Ich nehme nicht an einem Kurs teil','I am not enrolled in a course')}</label>${external?`<div class="v3-evidence"><h3>${t('Nachweis für externe Interessenten','Evidence for external applicants')}</h3><p>${t('Für diesen Weg wird ein geeigneter Nachweis benötigt. In der Vorschau kannst du einen Musternachweis hinzufügen.','This pathway requires suitable evidence. You can add a sample document in the preview.')}</p><button type="button" class="btn secondary" data-v3="housing-proof">${V3.housing.proof?t('Musternachweis ergänzt','Sample evidence added'):t('Musternachweis hinzufügen','Add sample evidence')}</button></div>`:''}<label class="field">${t('Deine Nachricht','Your message')}<textarea placeholder="${t('Dein Wunschzeitraum oder eine Frage zum Zimmer …','Your dates or a question about the room …')}"></textarea></label><label class="check-option"><input type="checkbox" required>${t('Ich verstehe, dass dies eine unverbindliche Formularvorschau ist.','I understand this is a non-binding form preview.')}</label><button type="submit" class="btn">${t('Musteranfrage vorbereiten','Prepare sample enquiry')}${arrow}</button><p id="v3-enquiry-status" role="status"></p></form>`}</section>`}
function v3Access(r){const housing=r.endsWith('/wohnen');return `<section class="v3-page-intro"><span class="eyebrow">${housing?'STAY IN AACHEN':'STUDIENKOLLEG AACHEN'}</span><h1>${t('Alles für deinen nächsten Schritt.','Everything for your next step.')}</h1><p>${t('Deine Unterlagen, Rückmeldungen und Termine an einem Ort.','Your documents, updates and appointments in one place.')}</p></section><section class="v3-section"><div class="v3-access"><div><h2>${t('Willkommen in deinem Bereich.','Welcome to your personal area.')}</h2><p>${t('Schon beworben? Hier begleitest du deinen weiteren Weg. In dieser Vorschau kannst du einen Beispielbereich erkunden, ohne ein Konto anzulegen.','Already applied? Follow your next steps here. This preview lets you explore a sample area without creating an account.')}</p><span class="v3-local-label">${t('Vorschau mit Beispieldaten','Preview with sample data')}</span>${link(t(housing?'Wohnbereich ansehen':'Meine Bewerbung ansehen',housing?'Explore housing area':'View my application'),housing?'/portal/tenant':'/portal/applicant')}${!housing?link(t('Mein Studium ansehen','Explore my study area'),'/portal/student','secondary'):''}</div><div class="soft"><h3>${t('Noch ganz am Anfang?','Just starting out?')}</h3><p>${t('Finde deinen passenden Einstieg oder sprich mit unserem Team.','Find your starting point or talk to our team.')}</p>${link(t('Persönliche Beratung','Personal guidance'),'/beratung','secondary')}</div></div></section>`}
function v3Info(r){if(r==='/team')return `<section class="v3-page-intro"><span class="eyebrow">STUDIENKOLLEG AACHEN</span><h1>${t('Menschen, die deinen Weg begleiten.','People supporting your journey.')}</h1><p>${t('Persönliche Orientierung und ein Team vor Ort in Aachen.','Personal guidance and a team in Aachen.')}</p></section>${v3Section(t('LEITUNG','LEADERSHIP'),'Laura Saboor',`<div class="v3-editorial"><img src="assets/laura-saboor.jpg" alt="Laura Saboor"><div><h3>Managing Director</h3><p>W2G Academy GmbH</p><p>${t('Von der ersten Orientierung bis zur Vorbereitung deines Bildungswegs: Das Team verbindet Studienvorbereitung, Sprache und Unterstützung beim Ankommen.','From initial orientation to preparation for your educational pathway, the team connects university preparation, language and arrival support.')}</p>${link(t('Kontakt aufnehmen','Get in touch'),'/kontakt')}</div></div>`)}`;if(r.startsWith('/campus'))return `<section class="v3-page-intro"><span class="eyebrow">AACHEN</span><h1>${t('Hier beginnt dein neuer Alltag.','Your new daily life starts here.')}</h1><p>${t('Lernen, neue Menschen kennenlernen und Aachen entdecken.','Learn, meet new people and discover Aachen.')}</p></section>${v3Section('CAMPUS',t('Raum zum Lernen.','Space to learn.'),`<div class="v3-gallery"><img src="assets/campus-classroom.jpg" alt="${t('Unterricht am Studienkolleg','Classroom at Studienkolleg')}"><img src="assets/campus-workshop.jpg" alt="${t('Bewerbungsworkshop','Application workshop')}"></div><p>${t('Unterricht und persönliche Vorbereitung gehören zusammen. Die Bilder geben Einblicke in den bestehenden Campusalltag.','Classes and personal preparation go together. These photographs offer a glimpse of existing campus life.')}</p>`)}${v3Section(t('DEINE STADT','YOUR CITY'),'Aachen',`<img class="v3-wide-photo" src="assets/aachen-dom.jpg" alt="Aachener Dom"><p>${t('Unser Standort liegt in der Theaterstraße 30–32, 52062 Aachen. Vereinbare einen Termin, bevor du uns besuchst.','Our location is Theaterstraße 30–32, 52062 Aachen. Please arrange an appointment before visiting.')}</p>${link(t('Besuch vereinbaren','Arrange a visit'),'/beratung')}`)}`;if(['/wissen','/faq','/help'].includes(r))return `<section class="v3-page-intro"><span class="eyebrow">${t('WISSEN & ORIENTIERUNG','KNOWLEDGE & GUIDANCE')}</span><h1>${t('Gute Antworten.<br>Ein klarer Start.','Good answers.<br>A clear start.')}</h1><p>${t('Studienvorbereitung, Sprache und Ankommen verständlich erklärt.','Understand university preparation, language learning and settling in.')}</p></section><section class="v3-section"><form id="v3-faq-search" class="v3-filter"><label>${t('Deine Frage','Your question')}<input id="v3-faq-query" value="${esc(V3.faq)}" placeholder="${t('Kurs, Unterlagen, Wohnen …','Course, documents, housing …')}"></label><button class="btn">${t('Suchen','Search')}</button></form>${v3FaqItems().filter(x=>x.join(' ').toLowerCase().includes(V3.faq.toLowerCase())).map(x=>`<details class="v3-faq"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')||`<p>${t('Keine passende Antwort gefunden. Die Beratung hilft dir weiter.','No matching answer found. Our advisory team can help.')}</p>`}${link(t('Persönlich nachfragen','Ask the team'),'/beratung','secondary')}</section>`;if(r==='/kontakt'||r==='/contact')return `<section class="v3-page-intro"><span class="eyebrow">${t('WIR SIND FÜR DICH DA','WE ARE HERE TO HELP')}</span><h1>${t('Lass uns über deinen Weg sprechen.','Let’s talk about your pathway.')}</h1><p>${t('Fragen zu Kursen, Bewerbung oder deinem Start in Aachen?','Questions about courses, your application or arrival in Aachen?')}</p></section><section class="v3-section"><div class="v3-card-grid two">${v3Card(t('Persönliche Beratung','Personal guidance'),t('Bereite deine Fragen vor und wähle deinen nächsten Schritt.','Prepare your questions and choose your next step.'),'/beratung',t('Beratung vorbereiten','Prepare guidance'))}<article class="v3-card"><div><h3>Studienkolleg Aachen</h3><p>Theaterstraße 30–32<br>52062 Aachen</p><p><a href="mailto:info@stk-aachen.de">info@stk-aachen.de</a><br><a href="tel:+4924199032292">+49 241 990 322 92</a></p><small>${t('Kontaktangaben der bestehenden Website','Contact details from the existing website')}</small></div></article></div></section>`;if(r==='/preise')return `<section class="v3-page-intro"><span class="eyebrow">${t('PREISE & LEISTUNGEN','PRICES & SERVICES')}</span><h1>${t('Das passende Angebot für deinen Weg.','The right offer for your pathway.')}</h1><p>${t('Kurswahl, Starttermin und zusätzliche Leistungen bestimmen dein Angebot. Lass dir Umfang und aktuelle Konditionen persönlich bestätigen.','Your course, start date and additional services determine your offer. Confirm the scope and current terms with the team.')}</p></section>${v3Section(t('DEINE AUSWAHL','YOUR CHOICE'),t('Was möchtest du planen?','What would you like to plan?'),`<div class="v3-card-grid">${v3Card('Studienkolleg',t('T, M, W und M/T: Angebote passend zu deinem Bildungsziel.','T, M, W and M/T offers for your educational goal.'),'/studienkolleg')}${v3Card(t('Deutsch & Prüfungen','German & exams'),t('Kursstufen, Vorbereitung und Prüfungen getrennt planen.','Plan language levels, preparation and examinations separately.'),'/sprachschule')}${v3Card(t('Wohnen','Housing'),t('Veröffentlichte Orientierungspreise für Zimmer in Aachen.','Published indicative room rates in Aachen.'),'/wohnen')}</div>${link(t('Aktuelles Angebot anfragen','Request current offer'),'/beratung')}`)}`;return null}
function v3Body(r){if(r==='/')return v3Home();if(r.startsWith('/mein-bereich'))return v3Access(r);if(r.startsWith('/wohnen')&&!r.includes('/zimmer/'))return v3Housing();const info=v3Info(r);if(info)return info;return v3OriginalBody(r)}
function v3Bind(){document.querySelectorAll('[data-v3]').forEach(el=>el.addEventListener('click',()=>{const action=el.dataset.v3,v=el.dataset.value;if(action==='menu'){V3.menu=!V3.menu;render()}if(action==='photo')vModal(t('Einblick in die Unterkunft','Inside the accommodation'),`<img src="${esc(v)}" alt="${t('Unterkunft','Accommodation')}" style="width:100%;max-height:70vh;object-fit:contain">`);if(action==='housing-enquire'){V3.housing.selected=v;V3.housing.month=document.getElementById('v3-movein').value;V3.housing.sent=false;location.hash='/wohnen/anfrage'}if(action==='housing-proof'){V3.housing.proof=true;el.textContent=t('Musternachweis ergänzt','Sample evidence added');document.getElementById('v3-enquiry-status').textContent='';}}));document.getElementById('v3-housing-filter')?.addEventListener('submit',e=>{e.preventDefault();V3.housing.type=document.getElementById('housing-type').value;V3.housing.street=document.getElementById('housing-street').value;V3.housing.max=Number(document.getElementById('housing-budget').value);render()});document.getElementById('v3-external')?.addEventListener('change',e=>{V3.housing.external=e.target.checked;render()});document.getElementById('v3-enquiry')?.addEventListener('submit',e=>{e.preventDefault();const external=document.getElementById('v3-external').checked;if(external&&!V3.housing.proof){document.getElementById('v3-enquiry-status').textContent=t('Bitte zuerst einen Musternachweis ergänzen.','Please add sample evidence first.');return}V3.housing.sent=true;render();toast(t('Musteranfrage vorbereitet. Nichts wurde versendet.','Sample enquiry prepared. Nothing was sent.'))});document.getElementById('v3-faq-search')?.addEventListener('submit',e=>{e.preventDefault();V3.faq=document.getElementById('v3-faq-query').value;render()});document.getElementById('v3-chat-form')?.addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('v3-question').value.trim();if(!q)return;const m=V2.notes[V2.context];m.messages.push({role:'user',text:q});const lower=q.toLowerCase();let answer=/preis|kosten|price|cost/.test(lower)?t('Für dein konkretes Angebot zählen Kurs, Starttermin und Leistungen. Die Beratung bestätigt die aktuellen Konditionen. Zimmerpreise findest du bei Stay in Aachen als veröffentlichte Orientierung.','Your offer depends on course, start date and services. Our team confirms current terms. Stay in Aachen lists published indicative room rates.'):/wohn|zimmer|room|housing/.test(lower)?t('Bei Stay in Aachen kannst du nach Zimmerart, Lage und Budget filtern. Wähle ein Zimmer und deinen Zeitraum für eine unverbindliche Anfrage. Freie Plätze werden persönlich bestätigt.','Filter Stay in Aachen by room type, location and budget. Choose a room and dates for an enquiry. Availability is confirmed personally.'):/medizin|medicine|biolog/.test(lower)?t('Für Medizin und Biologie ist der M-Kurs ein möglicher Vorbereitungsweg. Lass deinen Bildungsabschluss und Sprachstand prüfen, bevor du dich festlegst.','The M course is a possible preparation pathway for medicine and biology. Have your academic records and language level reviewed before deciding.'):/technik|engineer|mathe/.test(lower)?t('Der T-Kurs bereitet auf technische, mathematische und naturwissenschaftliche Studienrichtungen vor. Die Kursseite hilft dir bei der Orientierung.','The T course prepares for technical, mathematical and scientific subjects. Explore its course page for guidance.'):t('Ich kann dir in dieser Vorschau beim nächsten Schritt helfen: Kurs finden, Unterlagen vorbereiten oder ein Zimmer auswählen. Für deine individuelle Frage kannst du einen Beratungsbrief sammeln und das Team kontaktieren.','In this preview I can help with your next step: find a course, prepare documents or choose a room. Collect your individual questions in a guidance brief and contact the team.');m.messages.push({role:'assistant',text:answer});render()});document.querySelectorAll('.v3-nav details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.v3-nav details').forEach(other=>{if(other!==d)other.open=false})}));}
render=function(){const r=route().split('?')[0],internal=!visitorRoute(r);if(V2.lastRoute!==r)V3.menu=false;syncPersona(r);const a=contextArea(r);const status=document.getElementById('toast');if(status){status.textContent='';status.classList.remove('show')}document.documentElement.lang=state.lang;document.body.classList.toggle('v3-public',!internal);document.querySelector('body>.skip').textContent=t('Zum Inhalt','Skip to content');document.getElementById('app').innerHTML=(internal?vHeader():v3Header())+`<div class="${internal?'layout':'v3-layout'}"><main id="main" tabindex="-1" class="page" data-route="${esc(r)}" data-area="${a.id}">${v3Body(r)}${internal?v3OriginalFooter():v3Footer()}</main>${v3Assistant(a)}</div>`;bind();vBind();v3Bind();V2.lastRoute=r;};
window.addEventListener('hashchange',()=>{V3.menu=false});
render();

// The skip target is a landmark, not an application hash route. Bind once.
document.querySelector('body>.skip')?.addEventListener('click',event=>{event.preventDefault();const main=document.getElementById('main');main?.focus();main?.scrollIntoView({block:'start'});});
